// errorName maps a typed SDK error to the name the monitoring backend groups on.
func errorName(err error) string {
	switch err.(type) {
	case *SdkHttpError:
		return "SdkHttpError"
	case *SdkValidationError:
		return "SdkValidationError"
	case *SdkNetworkError:
		return "SdkNetworkError"
	case *SdkTimeoutError:
		return "SdkTimeoutError"
	default:
		return "error"
	}
}

// requestIDOf returns the request id carried by the typed SDK errors, if any.
func requestIDOf(err error) string {
	switch e := err.(type) {
	case *SdkHttpError:
		return e.RequestID
	case *SdkNetworkError:
		return e.RequestID
	case *SdkTimeoutError:
		return e.RequestID
	default:
		return ""
	}
}

const sourceContextLines = 5

// frameInApp reports whether a source file belongs to the application rather
// than the Go runtime or an installed module.
func frameInApp(file string) bool {
	if file == "" {
		return false
	}
	if strings.Contains(file, "/pkg/mod/") {
		return false
	}
	if root := runtime.GOROOT(); root != "" && strings.HasPrefix(file, root) {
		return false
	}
	return true
}

// frameSourceContext reads a few lines around a frame so the dashboard can show
// the original code (best-effort: the source must be readable at runtime).
func frameSourceContext(file string, line int) map[string]any {
	if file == "" || line < 1 {
		return nil
	}
	data, err := os.ReadFile(file)
	if err != nil {
		return nil
	}
	lines := strings.Split(string(data), "\n")
	if line > len(lines) {
		return nil
	}
	idx := line - 1
	ctx := map[string]any{"contextLine": lines[idx]}
	start := idx - sourceContextLines
	if start < 0 {
		start = 0
	}
	if pre := lines[start:idx]; len(pre) > 0 {
		ctx["preContext"] = pre
	}
	end := idx + 1 + sourceContextLines
	if end > len(lines) {
		end = len(lines)
	}
	if post := lines[idx+1 : end]; len(post) > 0 {
		ctx["postContext"] = post
	}
	return ctx
}

// shortFuncName trims the package path from a fully-qualified function name.
func shortFuncName(fn string) string {
	if i := strings.LastIndex(fn, "/"); i >= 0 {
		fn = fn[i+1:]
	}
	return fn
}

// buildFrames captures the call stack at the failing SDK boundary (innermost
// first), with original-source context per frame, dropping the SDK's own
// logging plumbing from the top.
func buildFrames() []map[string]any {
	pcs := make([]uintptr, 64)
	n := runtime.Callers(2, pcs) // skip runtime.Callers + buildFrames
	if n == 0 {
		return nil
	}
	callerFrames := runtime.CallersFrames(pcs[:n])
	out := make([]map[string]any, 0, n)
	for {
		fr, more := callerFrames.Next()
		name := shortFuncName(fr.Function)
		if len(out) == 0 && (strings.Contains(name, "logError") || strings.Contains(name, "logAndReturn")) {
			if !more {
				break
			}
			continue
		}
		frame := map[string]any{
			"function": name,
			"filename": fr.File,
			"lineno":   fr.Line,
			"inApp":    frameInApp(fr.File),
		}
		for k, v := range frameSourceContext(fr.File, fr.Line) {
			frame[k] = v
		}
		out = append(out, frame)
		if !more {
			break
		}
	}
	return out
}
